// ============================================================================
// ROUTE 2: INBOUND INQUIRY PARSER & DATA NORMALIZATION
// ============================================================================
const body = $json.body || $json;

// Detect WhatsApp Cloud API structure
const entry = body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const waMsg = change?.messages?.[0];
const waContact = change?.contacts?.[0];

let channel = 'WhatsApp';
let sender = '';
let name = 'Studio Prospect';
let query = '';

if (waMsg) {
  channel = 'WhatsApp';
  sender = waMsg.from || '';
  name = waContact?.profile?.name || 'WhatsApp Client';
  query = waMsg.text?.body || waMsg.caption || 'Studio Inquiry';
} else {
  channel = body.channel?.toLowerCase() === 'email' || (body.from && body.from.includes('@')) ? 'Email' : 'WhatsApp';
  sender = body.from || body.email || body.phone || 'client@sutrastudio.com';
  name = body.name || 'Studio Client';
  query = body.message || body.text || body.query || body.subject || 'Studio inquiry regarding commissions';
}

// Mask identifier for safety
let maskedFrom = sender;
if (sender.includes('@')) {
  const [u, d] = sender.split('@');
  maskedFrom = `${u.slice(0, 2)}***@${d}`;
} else if (sender.length > 7) {
  maskedFrom = `${sender.slice(0, 3)} **** ${sender.slice(-4)}`;
}

return [{
  json: {
    channel,
    sender,
    maskedFrom,
    name,
    query,
    receivedAt: new Date().toISOString()
  }
}];

